return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'ug_CN','project-id-version'=>'Babilim 1.0.0','pot-creation-date'=>'2026-10-31T05:53:36+00:00','po-revision-date'=>'2026-10-31T05:53:36+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'تور بېكىتىڭىزگە ئورنىتىلغان قىستۇرمىلار ۋە ئۆرنەكلەردىكى كەم تەرجىمىلەرنى تولدۇرىدۇ.','Translations'=>'تەرجىمىلەر','Babilim Settings'=>'Babilim تەڭشەكلىرى','Settings'=>'تەڭشەكلەر','You are not allowed to do this.'=>'سىزنىڭ بۇ مەشغۇلاتنى ئىجرا قىلىشىڭىزغا رۇخسەت يوق.','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'تېخىمۇ ئاز زاپچاس تاللاڭ: ھەر قېتىمدا ئەڭ كۆپ بولغاندا %1$d مەشغۇلات (سىز %2$d تاللىدىڭىز).','That component is not installed on this site, so a translation cannot be requested for it.'=>'بۇ زاپچاس بۇ تور بېكەتتە ئورنىتىلمىغان، شۇڭلاشقا ئۇنىڭ ئۈچۈن تەرجىمە تەلەپ قىلغىلى بولمايدۇ.','Already installed.'=>'ئورنىتىلغان.','Downloaded and installed.'=>'چۈشۈرۈلۈپ ئورنىتىلدى.','Babilim has not been enabled for this site yet.'=>'Babilim بۇ تور بېكەتتە تېخى قوزغىتىلمىغان.','No build is available to download for this locale.'=>'بۇ تىل ئۈچۈن چۈشۈرۈشكە بولىدىغان قۇرۇلما نەشرى يوق.','Rolled back to the previous build.'=>'ئالدىنقى قۇرۇلما نەشرىگە قايتۇرۇلدى.','Rolled back and reported.'=>'قايتۇرۇلۇپ دوكلات قىلىندى.','Rolled back, but the report could not be sent: %s'=>'قايتۇرۇلدى، لېكىن دوكلاتنى ئەۋەتكىلى بولمىدى: %s','Removed.'=>'ئۆچۈرۈلدى.','Translation requested.'=>'تەرجىمە تەلەپ قىلىندى.','This component was already uploaded. Babilim is checking it now.'=>'بۇ زاپچاس ئاللىقاچان يۈكلەنگەن. Babilim ھازىر ئۇنى تەكشۈرۈۋاتىدۇ.','Upload cancelled.'=>'يۈكلەش بىكار قىلىندى.','Upload complete — translation requested.'=>'يۈكلەش تامام — تەرجىمە تەلەپ قىلىندى.','This component does not declare a version number, so a translation cannot be requested for it.'=>'بۇ زاپچاس نەشر نومۇرىنى ئاشكارىلىمىغان، شۇڭلاشقا ئۇنىڭ ئۈچۈن تەرجىمە تەلەپ قىلغىلى بولمايدۇ.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'بۇ زاپچاسنىڭ نەشر نومۇرى %d ھەرپتىن ئۇزۇن، Babilim ئۇنى بىر تەرەپ قىلالمايدۇ، شۇڭلاشقا ئۇنىڭ ئۈچۈن تەرجىمە تەلەپ قىلغىلى بولمايدۇ.','A translation cannot be requested for that locale on this site right now.'=>'ھازىر بۇ تور بېكەتتە بۇ تىل ئۈچۈن تەرجىمە تەلەپ قىلغىلى بولمايدۇ.','Thank you. Your report was sent.'=>'رەھمەت. دوكلاتىڭىز ئەۋەتىلدى.','This report does not name a valid plugin or theme and locale.'=>'بۇ دوكلاتتا ئىناۋەتلىك قىستۇرما ياكى ئۆرنەك ۋە تىل ئېنىق كۆرسىتىلمىگەن.','Please choose a category for this report.'=>'بۇ دوكلات ئۈچۈن بىر تۈر تاللاڭ.','This report is missing a valid build to report against.'=>'بۇ دوكلاتقا ماس كېلىدىغان ئىناۋەتلىك قۇرۇلما نەشرى يوق.','This build is not one this site currently knows about for this component/locale.'=>'بۇ قۇرۇلما نەشرى بۇ تور بېكەتنىڭ ھازىر بۇ زاپچاس/تىل ئۈچۈن بىلىدىغان نەشرى ئەمەس.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'"%1$s" مەيدانى بەك ئۇزۇن: ئۇ %2$d ھەرپتىن تەركىب تاپقان، چەك بولسا %3$d. ھېچنېمە ئەۋەتىلمىدى؛ قىسقارتىپ قايتا سىناڭ.','Original string'=>'ئەسلى تېكىست','String context'=>'تېكىستنىڭ تىل مۇھىتى','Current translation'=>'نۆۋەتتىكى تەرجىمە','Suggested translation'=>'تەۋسىيە قىلىنغان تەرجىمە','Note (optional)'=>'ئىزاھات (ئىختىيارىي)','Where you saw this (optional)'=>'بۇنى قەيەردە كۆردىڭىز (ئىختىيارىي)','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Babilim ماس قەدەملەشتۈرۈشى مۇلازىمەت تەرىپىدىن ۋاقىتلىق كېچىكتۈرۈلدى (چەكلەندى)؛ %s دىن كېيىن قايتا سىنايدۇ.','That is not a valid WordPress locale code. Nothing was saved.'=>'بۇ ئىناۋەتلىك WordPress تىل كودى ئەمەس. ھېچنېمە ساقلانمىدى.','Settings saved.'=>'تەڭشەكلەر ساقلاندى.','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'ئەگەر بۇ تاللانما قوزغىتىلسا، قىستۇرمىنى ئۆچۈرگەندە بۇ تور بېكەتنىڭ كىملىكىمۇ ئۆچۈرۈلىدۇ. ئۇنىڭدىن كېيىن بۇ تور بېكەتكە باغلانغان ھەقلىق ئىجازەتنامىنى ئاپتوماتىك ئەسلىگە كەلتۈرگىلى بولمايدۇ؛ ئۇنى قايتۇرۇۋېلىش ئۈچۈن Babilim قوللىشى بىلەن %s ئارقىلىق ئالاقىلىشىشىڭىز كېرەك.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim قىستۇرما ئۆچۈرۈلگەندە بۇ تور بېكەتنىڭ كىملىكىنى ئۆچۈرۈۋېتىشكە تەڭشەلگەن. ئۇنىڭدىن كېيىن بۇ تور بېكەتكە باغلانغان ھەقلىق ئىجازەتنامىنى ئاپتوماتىك ئەسلىگە كەلتۈرگىلى بولمايدۇ؛ ئۇنى قايتۇرۇۋېلىش ئۈچۈن Babilim قوللىشى بىلەن %s ئارقىلىق ئالاقىلىشىشىڭىز كېرەك. كىملىكنى ساقلاپ قېلىش ئۈچۈن «ۋاز كېچىش» نى چېكىڭ، Babilim تەڭشەكلىرىدىكى «ئورنىتىلمىغاندا Babilim نىڭ بارلىق سانلىق مەلۇماتلىرىنى ئۆچۈرۈش» تاللانمىسىدىكى بەلگىنى ئېلىۋېتىڭ، ئاندىن قايتا توختىتىڭ. بەرىبىر توختىتامسىز؟','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'بۇ كۆپ تور بېكەتلىك تورداتىكى %1$d تور بېكەت قىستۇرما ئۆچۈرۈلگەندە ئۆزىنىڭ Babilim كىملىكىنى ئۆچۈرۈۋېتىشكە تەڭشەلگەن. ئۇنىڭدىن كېيىن ئۇ تور بېكەتكە باغلانغان ھەقلىق ئىجازەتنامىنى ئاپتوماتىك ئەسلىگە كەلتۈرگىلى بولمايدۇ؛ ئۇنى قايتۇرۇۋېلىش ئۈچۈن Babilim قوللىشى بىلەن %2$s ئارقىلىق ئالاقىلىشىشىڭىز كېرەك. كىملىكنى ساقلاپ قېلىش ئۈچۈن «ۋاز كېچىش» نى چېكىڭ، ئۇ تور بېكەتنىڭ Babilim تەڭشەكلىرىدىكى «ئورنىتىلمىغاندا Babilim نىڭ بارلىق سانلىق مەلۇماتلىرىنى ئۆچۈرۈش» تاللانمىسىدىكى بەلگىنى ئېلىۋېتىڭ، ئاندىن قايتا توختىتىڭ. بەرىبىر توختىتامسىز؟' . "\0" . 'بۇ كۆپ تور بېكەتلىك تورداتىكى %1$d تور بېكەت قىستۇرما ئۆچۈرۈلگەندە ئۆزىنىڭ Babilim كىملىكىنى ئۆچۈرۈۋېتىشكە تەڭشەلگەن. ئۇنىڭدىن كېيىن ئۇ تور بېكەتلەرگە باغلانغان ھەقلىق ئىجازەتنامىنى ئاپتوماتىك ئەسلىگە كەلتۈرگىلى بولمايدۇ؛ ئۇنى قايتۇرۇۋېلىش ئۈچۈن Babilim قوللىشى بىلەن %2$s ئارقىلىق ئالاقىلىشىشىڭىز كېرەك. كىملىكلەرنى ساقلاپ قېلىش ئۈچۈن «ۋاز كېچىش» نى چېكىڭ، ھەر بىر تور بېكەتنىڭ Babilim تەڭشەكلىرىدىكى «ئورنىتىلمىغاندا Babilim نىڭ بارلىق سانلىق مەلۇماتلىرىنى ئۆچۈرۈش» تاللانمىسىدىكى بەلگىنى ئېلىۋېتىڭ، ئاندىن قايتا توختىتىڭ. بەرىبىر توختىتامسىز؟','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'بۇ كۆپ تور بېكەتلىك تور (network) تا تور بېكەتلەر بەك كۆپ بولغاچقا، ئۇلارنى بىرمۇبىر تەكشۈرگىلى بولمايدۇ، ئۇلارنىڭ بەزىلىرى قىستۇرما ئۆچۈرۈلگەندە Babilim كىملىكىنى ئۆچۈرۈۋېتىشكە تەڭشەلگەن بولۇشى مۇمكىن. ئۇنداق تور بېكەتكە باغلانغان ھەقلىق ئىجازەتنامىنى ئاپتوماتىك ئەسلىگە كەلتۈرگىلى بولمايدۇ؛ ئۇنى قايتۇرۇۋېلىش ئۈچۈن Babilim قوللىشى بىلەن %s ئارقىلىق ئالاقىلىشىشىڭىز كېرەك. كىملىكلەرنى ساقلاپ قېلىش ئۈچۈن «ۋاز كېچىش» نى چېكىڭ، ھەر بىر تور بېكەتنىڭ Babilim تەڭشەكلىرىدىكى «ئورنىتىلمىغاندا Babilim نىڭ بارلىق سانلىق مەلۇماتلىرىنى ئۆچۈرۈش» تاللانمىسىدىكى بەلگىنى ئېلىۋېتىڭ، ئاندىن قايتا توختىتىڭ. بەرىبىر توختىتامسىز؟','Open Babilim settings'=>'Babilim تەڭشىكىنى ئېچىش','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim بۇ سایىتنى دەلىللىيەلمىدى، شۇڭا ھېچنېمە چۈشۈرۈلمەيدۇ ياكى ئورنىتىلمايدۇ.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'مۇلازىمەت سایىتىڭىزغا ئۇلىنالمىدى. ئوت تامى، بىخەتەرلىك قىستۇرمىسى ياكى ساھىبجاي قائىدىسى تەلەپنى توسۇۋاتقان بولۇشى مۇمكىن؛ /wp-json/babilim/v1/challenge غا بولغان تەلەپلەرگە يول قويۇڭ.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'سایىتىڭىزنىڭ جاۋاب قايتۇرۇشىغا بەك ئۇزۇن ۋاقىت كەتتى. سەل تۇرۇپ قايتا سىناڭ، ھەمدە ساھىبجايىڭىزنىڭ بەك ئاستا ئەمەسلىكىنى ياكى ھەددىدىن زىيادە يۈكلەنمىگەنلىكىنى تەكشۈرۈڭ.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'تور بېكىتىڭىز جاۋاب قايتۇردى، ئەمما كۈتكەن مەزمۇن ئەمەس. REST API باشقا قىستۇرما تەرىپىدىن قايتا يېزىلغان بولۇشى ياكى بۇ ئۇلانما ۋاقىتلىق ساقلانغان بولۇشى مۇمكىن؛ /wp-json/babilim/v1/challenge نى ۋاقىتلىق ساقلاش ۋە قايتا يېزىشتىن مۇستەسنا قىلىڭ.','Please check that your site can be reached from the internet, then try again.'=>'سایىتىڭىزنىڭ ئىنتېرنېتتىن زىيارەت قىلىنالايدىغانلىقىنى تەكشۈرۈپ، ئاندىن قايتا سىناڭ.','Re-verify'=>'قايتا دەلىللەش','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'بۇ سایىتنىڭ چوڭلۇقى مۇلازىمەت بىر قېتىملىق قەدەمداشلاشتا قوبۇل قىلىدىغان چەكتىن ئېشىپ كەتتى، شۇڭا بەزى تۈرلەر قالدۇرۇلدى: %1$d زاپچاس ۋە %2$d تىل.','This site is verified.'=>'بۇ سایىت دەلىللەندى.','Registration restarted.'=>'تىزىملاتقۇزۇش قايتا باشلاندى.','Sync complete.'=>'ماس قەدەملەش تامام بولدى.','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim بۇ سایىتنى قوزغىتىپ تەكشۈرمەكتە… بۇ بەتنى قايتا يۈكلەڭ ياكى كۈنتەرتىپكە قويۇلغان تەكشۈرۈشنىڭ تاماملىنىشىنى كۈتۈڭ.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim قوزغىتىشنى تاماملىيالمىدى (%1$s): %2$s','A host that serves only one PHP request at a time cannot complete this step.'=>'بىرلا ۋاقىتتا پەقەت بىر PHP تەلىپىنى بىر تەرەپ قىلىدىغان ساھىبجاي بۇ باسقۇچنى تاماملىيالمايدۇ.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim قوزغىتىلدى: بۇ تور بېكەت دەلىللەندى ۋە %d زاپچاس تېپىلدى.' . "\0" . 'Babilim قوزغىتىلدى: بۇ تور بېكەت دەلىللەندى ۋە %d زاپچاس تېپىلدى.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim ئوچۇرۇلدى. ئەمدى ھېچنېمە ئەۋەتىلمەيدۇ؛ ئورنىتىلغان تەرجىمىلەر داۋاملىق ئىشلەيدۇ.','Supplementary translation index rebuilt.'=>'قوشۇمچە تەرجىمە ئىندېكسى قايتا قۇرۇلدى.','Sweep complete: %d file deleted.'=>'تازىلاش تامام بولدى: %d ھۆججەت ئۆچۈرۈلدى.' . "\0" . 'تازىلاش تامام بولدى: %d ھۆججەت ئۆچۈرۈلدى.','Removed %d installed component.'=>'ئورنىتىلغان %d زاپچاس چىقىرىۋېتىلدى.' . "\0" . 'ئورنىتىلغان %d زاپچاس چىقىرىۋېتىلدى.','Automatic installs are now off; turn them on again in the settings if you want them.'=>'ئاپتوماتىك ئورنىتىش ھازىر تاقالدى؛ ئەگەر لازىم بولسا تەڭشەكلەردە قايتا ئېچىڭ.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim بۇ سایىتتىكى تىلىڭىزغا تەرجىمىسى يوق قىستۇرما ۋە ئۇسلۇبلارنى تېپىپ، ھەر بىرىگە بىردىن تەرجىمە ئورنىتىدۇ.','Languages found on this site: %s.'=>'بۇ سایىتتا تېپىلغان تىللار: %s.','Available translations can be installed with one click, and missing ones can be requested. After that, new translations and updates are installed automatically (on the free plan, only for plugins and themes that already use a free slot).'=>'بار تەرجىمىلەرنى بىر چېكىشتە ئورنىتىشقا، كەم تەرجىمىلەرنى تەلەپ قىلىشقا بولىدۇ. ئۇنىڭدىن كېيىن يېڭى تەرجىمىلەر ۋە يېڭىلانمىلار ئاپتوماتىك ئورنىتىلىدۇ (ھەقسىز بولاقتا پەقەت ھەقسىز ئورۇننى ئىشلىتىۋاتقان قىستۇرما ۋە باشتېمىلارغىلا).','The free plan covers a limited number of plugins and themes; your exact quota is shown in Settings after you enable Babilim.'=>'ھەقسىز بولاق چەكلىك سانلىق قىستۇرما ۋە باشتېمىلارنى ئۆز ئىچىگە ئالىدۇ؛ Babilim نى قوزغاتقاندىن كېيىن، ئېنىق نورمىڭىز تەڭشەكلەردە كۆرسىتىلىدۇ.','What is sent when you enable Babilim'=>'Babilim نى قوزغاتقاندا ئەۋەتىلىدىغان مەزمۇن','Enabling…'=>'قوزغىتىلىۋاتىدۇ…','Enable Babilim'=>'Babilim نى قوزغىتىش','By clicking Enable, you agree to send the information listed above to Babilim.'=>'«قوزغىتىش» نى چەككىنىڭىزدە، يۇقىرىدا كۆرسىتىلگەن ئۇچۇرلارنى Babilim غا ئەۋەتىشكە قوشۇلغان بولىسىز.','Check again now'=>'ھازىر قايتا تەكشۈرۈش','Babilim installed %d translation automatically since your last visit.'=>'ئاخىرقى زىيارىتىڭىزدىن بۇيان Babilim %d تەرجىمىنى ئاپتوماتىك ئورناتتى.' . "\0" . 'ئاخىرقى زىيارىتىڭىزدىن بۇيان Babilim %d تەرجىمىنى ئاپتوماتىك ئورناتتى.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim بۇ سایىتنى قوزغىتىپ تەكشۈرمەكتە… (ئاخىرقى سىناق: %s)','Check again'=>'قايتا تەكشۈرۈش','No components synced yet.'=>'تېخى ھېچقانداق زاپچاس قەدەمداشلانمىدى.','%d succeeded'=>'%d مۇۋەپپەقىيەتلىك بولدى' . "\0" . '%d مۇۋەپپەقىيەتلىك بولدى','%d skipped'=>'%d ئاتلاپ ئۆتۈلدى' . "\0" . '%d ئاتلاپ ئۆتۈلدى','%d failed'=>'%d مەغلۇب بولدى' . "\0" . '%d مەغلۇب بولدى','%d not yet tried'=>'%d تېخى سىنالمىدى' . "\0" . '%d تېخى سىنالمىدى','%1$s nothing to do.'=>'%1$s قىلىدىغان ئىش يوق.','%1$s %2$s.'=>'%1$s %2$s.','Bulk download:'=>'تۈركۈملەپ چۈشۈرۈش:','Bulk update:'=>'تۈركۈملەپ يېڭىلاش:','Bulk request:'=>'تۈركۈملەپ تەلەپ قىلىش:','per day'=>'ھەر كۈنى','Wrong meaning'=>'مەنىسى خاتا','Wrong term'=>'ئاتالغۇ خاتا','Broken placeholder'=>'ئورۇن بەلگىسى بۇزۇلغان','Wrong for this context'=>'بۇ مەزمۇنغا ماس كەلمەيدۇ','Wrong plural form'=>'خاتا كۆپلۈك شەكلى','Negation reversed'=>'ئىنكار مەنىسى ئەكسىچە بولۇپ قالغان','Translation does not load'=>'تەرجىمە يۈكلەنمەيدۇ','problem report categoryOther'=>'باشقا','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','Continuing…'=>'داۋاملاشتۇرۇلۇۋاتىدۇ…','Continue next batch (%d left)'=>'كېيىنكى تۈركۈمنى داۋاملاشتۇرۇش (%d قالدى)','Search components'=>'زاپچاسلارنى ئىزدە','These are the languages this site uses. You can change them in %s.'=>'بۇلار بۇ تور بېكەت ئىشلىتىدىغان تىللار. ئۇلارنى %s ئارقىلىق ئۆزگەرتەلەيسىز.','Upload this component?'=>'بۇ زاپچاسنى يۈكلەمسىز؟','There is no upload waiting for confirmation.'=>'جەزملەشنى كۈتىۋاتقان يۈكلەش يوق.','Back'=>'قايتىش','To translate this component, Babilim needs its source.'=>'بۇ بۆلەكنى تەرجىمە قىلىش ئۈچۈن Babilim نىڭ ئۇنىڭ مەنبەسى بولۇشى كېرەك.','The entire plugin or theme directory of %1$s (version %2$s) will be uploaded to Babilim.'=>'%1$s (نەشرى %2$s) نىڭ پۈتۈن قىستۇرما ياكى ئۆرنەك مۇندەرىجىسى Babilim غا يۈكلىنىدۇ.','If that directory contains keys, logs or customer data, they will be uploaded too. The service removes common sensitive files (configuration, environment, database dumps, logs, keys) but cannot guarantee it finds everything.'=>'ئەگەر بۇ مۇندەرىجىدە ئاچقۇچلار، خاتىرىلەر ياكى خېرىدارلارنىڭ سانلىق مەلۇماتلىرى بولسا، ئۇلارمۇ يۈكلىنىدۇ. مۇلازىمەت كۆپ ئۇچرايدىغان سەزگۈر ھۆججەتلەرنى (سەپلىمە، مۇھىت، سانداننىڭ چىقىرىلغان نۇسخىلىرى، خاتىرىلەر، ئاچقۇچلار) چىقىرىۋېتىدۇ، ئەمما ھەممىسىنى تاپالايدىغانلىقىغا كاپالەتلىك قىلالمايدۇ.','The upload is kept until you ask Babilim to delete it.'=>'يۈكلەنگەن مەزمۇن سىز Babilim دىن ئۆچۈرۈشنى تەلەپ قىلغانغا قەدەر ساقلىنىدۇ.','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'ئۇ بۇ مۇلازىمەتنىڭ مۇلازىمېتىر ساھىبخانىلىق تەمىنلىگۈچىسى تەرىپىدىن ساقلىنىدۇ ھەمدە تەرجىمە ھاسىل قىلىش ئۈچۈن AI مودېللىرى تەرىپىدىن بىر تەرەپ قىلىنىدۇ.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'ئەسلى تېكىست ۋە ئۇنىڭدىن ياسالغان تەرجىمىلەر ئوخشاش نەشرىنى قاچىلىغان باشقا تور بېكەتلەرگە تەمىنلىنىدۇ.','By continuing you confirm that you have the right to upload this component.'=>'داۋاملاشتۇرسىڭىز، بۇ بۆلەكنى يۈكلەشكە ھوقۇقىڭىز بارلىقىنى جەزملەشتۈرگەن بولىسىز.','Upload and request'=>'يۈكلەپ تەلەپ قىلىش','Uploading…'=>'يۈكلىنىۋاتىدۇ…','Cancel'=>'ئەمەلدىن قالدۇرۇش','Uploading'=>'يۈكلىنىۋاتىدۇ','There is no upload in progress.'=>'ئىجرا بولۇۋاتقان يۈكلەش يوق.','Uploading part %1$d of %2$d…'=>'%2$d پارچىنىڭ %1$d-پارچىسى يۈكلىنىۋاتىدۇ…','Continue'=>'داۋاملاشتۇرۇش','Confirm'=>'جەزملەش','Remove'=>'چىقىرىۋېتىش','Roll back'=>'ئەسلىگە قايتۇرۇش','Nothing to confirm.'=>'جەزملەيدىغان ھېچنېمە يوق.','Choose a language'=>'بىر تىل تاللاڭ','Roll back and report'=>'ئەسلىگە قايتۇرۇپ دوكلات قىلىش','Report a problem'=>'مەسىلە دوكلات قىلىش','Nothing to choose.'=>'تاللايدىغان ھېچنېمە يوق.','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. تىلنى تاللاڭ.','Supplementary translations'=>'تولۇقلىما تەرجىمىلەر','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'ھەر بىر بۆلەكنىڭ ھەر بىر تىلنىڭ ئورتاق سۈكۈتتىكى دائىرە تولۇقلىمىسىغا قوشقان ئۆز تۆھپىسى.','Component'=>'بۆلەك','Language'=>'تىل','Included in index'=>'ئىندېكسقا كىرگۈزۈلگەن','Entries'=>'تۈرلەر','Conflicting keys'=>'توقۇنۇشقان ئاچقۇچلار','Yes'=>'ھەئە','No — component inactive'=>'ياق — بۆلەك ئاكتىپ ئەمەس','No — installed version differs from the active one'=>'ياق — ئورنىتىلغان نەشرى ئاكتىپ نەشرىدىن پەرقلىنىدۇ','No — component removed'=>'ياق — بۆلەك ئۆچۈرۈلگەن','No'=>'ياق','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'بۇنى پەقەت تور باشقۇرغۇچىسى قىلالايدۇ، چۈنكى بۇ مەزكۇر تورداتىكى بارلىق بېكەتلەر ئورتاق ئىشلىتىدىغان تەرجىمە ھۆججەتلىرىنى ئۆزگەرتىدۇ.','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim بۇ بېكەتنى دەلىللەشنى تامامىلىيالمىدى (مۇلازىمەت ئۇنىڭغا قايتا ئۇلىنالمىدى). تىزىملاش توختىتىلدى.','This site already has an active registration that can no longer be recovered automatically.'=>'بۇ بېكەتتە ئاپتوماتىك ئەسلىگە كەلتۈرگىلى بولمايدىغان ئاكتىپ تىزىملىتىش بار.','Restart registration'=>'تىزىملاشنى قايتا باشلاش','Babilim settings'=>'Babilim تەڭشەكلىرى','General'=>'ئادەتتىكى','Advanced'=>'ئالىي','Languages'=>'تىللار','Automatic installs'=>'ئاپتوماتىك ئورنىتىش','Install available translations automatically'=>'ئىشلەتكىلى بولىدىغان تەرجىمىلەرنى ئاپتوماتىك ئورنىتىش','On the free plan, only components that already use one of your free slots are installed automatically, so no new slot is taken.'=>'ھەقسىز بولاقتا، ھەقسىز ئورۇنلىرىڭىزنىڭ بىرىنى ئىشلىتىۋاتقان بۆلەكلەرلا ئاپتوماتىك ئورنىتىلىدۇ، شۇڭا يېڭى ئورۇن ئىگىلەنمەيدۇ.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'بۇ بېكەت كۆپ بېكەتلىك تورنىڭ بىر قىسمى بولۇپ، يېڭى تەرجىمىلەر ئاپتوماتىك ئورنىتىلمايدۇ. ئورنىتىلغان تەرجىمىلەر يەنىلا يېڭىلىنىدۇ.','Custom overrides'=>'ئىختىيارى قاپلاشلار','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'ھەممىنى تازىلىغاندا ياكى بۇ قىستۇرمىنى ئۆچۈرگەندە ئۆزۈم يازغان تەرجىمە قاپلاشلىرىمنى ساقلاپ قال.','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'سىز %s غا قويغان تەرجىمە ھۆججەتلىرى ھەمىشە Babilim نىڭكىدىن ئاۋۋال ئىشلىتىلىدۇ. بۇ تاللاشنى بىكار قىلمىسىڭىز ئۇلار ساقلىنىدۇ.','Uninstall'=>'ئورنىتىشنى ئۆچۈرۈش','Delete all Babilim data on uninstall'=>'ئورنىتىشتىن قالدۇرغاندا Babilim نىڭ بارلىق سانلىق مەلۇماتلىرىنى ئۆچۈرۈش','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'سۈكۈتتە ئېتىك: قىستۇرمىنى ئۆچۈرگەندە بۇ بېكەتنىڭ كىملىكى ساقلىنىدۇ، شۇڭا قايتا ئورنىتىلغاندا ئۇنى قايتا ئىشلەتكىلى بولىدۇ.','Account'=>'ھېساباتىم','Save changes'=>'ئۆزگەرتىشلەرنى ساقلاش','Disable Babilim'=>'Babilim نى چەكلەش','Installed translations are kept, but no further checks or downloads will run.'=>'ئورنىتىلغان تەرجىمىلەر ساقلىنىدۇ، لېكىن بۇنىڭدىن كېيىن تەكشۈرۈش ياكى چۈشۈرۈش ئىجرا قىلىنمايدۇ.','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Babilim نى چەكلەمسىز؟ ئورنىتىلغان تەرجىمىلەر ساقلىنىدۇ، لېكىن بۇنىڭدىن كېيىن تەكشۈرۈش ياكى چۈشۈرۈش ئىجرا قىلىنمايدۇ.','This site is not registered with Babilim yet.'=>'بۇ بېكەت تېخى Babilim غا تىزىملاتمىغان.','This site is already licensed. Reload the page.'=>'بۇ بېكەتنىڭ ئىجازەتنامىسى بار. بەتنى قايتا يۈكلەڭ.','Checkout is not available for this site right now.'=>'بۇ بېكەت ئۈچۈن ھازىر پۇل تۆلەش ئىقتىدارىنى ئىشلەتكىلى بولمايدۇ.','Could not start checkout: %s'=>'پۇل تۆلەشنى باشلىغىلى بولمىدى: %s','Babilim is not enabled.'=>'Babilim قوزغىتىلمىغان.','Not registered yet'=>'تېخى تىزىملاتمىغان','Not verified'=>'دەلىللەنمىگەن','Verified'=>'دەلىللەنگەن','Status'=>'ھالەت','Licensed'=>'ئىجازەتلىك','Partner'=>'ھەمكارلاشقۇچى','Free'=>'ھەقسىز','License'=>'ئىجازەتنامە','Upgrade this site'=>'بۇ بېكەتنى يۈكسەلدۈرۈش','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'بۇ تور بېكەت ئۈچۈن بىر قېتىملىق سېتىۋېلىش: %1$s %2$s. كېلەچەكتىكى بارلىق تەرجىمە يېڭىلانمىلىرىنى ئۆز ئىچىگە ئالىدۇ. چىقىم تۆلەش يېڭى بەتكۈچتە Paddle ئارقىلىق بىر تەرەپ قىلىنىدۇ.','This issues a new restore code and the previous one stops working. Continue?'=>'بۇ يېڭى ئەسلىگە كەلتۈرۈش كودى بېرىدۇ، ئالدىنقى كود ئىناۋەتسىز بولىدۇ. داۋاملاشتۇرامسىز؟','Show a new restore code'=>'يېڭى ئەسلىگە كەلتۈرۈش كودىنى كۆرسىتىش','rc_…'=>'rc_…','Restore code'=>'ئەسلىگە كەلتۈرۈش كودى','Restore purchase'=>'سېتىۋېلىشنى ئەسلىگە كەلتۈرۈش','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'بۇ دائىرە نامى ئۈچۈن ئىجازەتنامە سېتىۋالغانمۇ؟ ھېسابلاشتا تاپشۇرۇۋالغان ئەسلىگە كەلتۈرۈش كودىنى كىرگۈزۈڭ.','That does not look like a restore code.'=>'بۇ ئەسلىگە كەلتۈرۈش كودىغا ئوخشىمايدۇ.','This restore code was not recognised for this site.'=>'بۇ ئەسلىگە كەلتۈرۈش كودى مەزكۇر بېكەتتە تونۇلمىدى.','Too many attempts. Try again tomorrow.'=>'سىناش قېتىم سانى بەك كۆپ. ئەتە قايتا سىناڭ.','This site must be verified first.'=>'بۇ تور بېكەتنى ئالدىدا دەلىللەش كېرەك.','Could not restore the purchase: %s'=>'سېتىۋېلىشنى ئەسلىگە كەلتۈرگىلى بولمىدى: %s','Purchase restored. This site is now licensed.'=>'سېتىۋېلىش ئەسلىگە كەلتۈرۈلدى. بۇ تور بېكەت ئەمدى ئىجازەتلىك.','This site has no purchase to show a code for.'=>'بۇ تور بېكەتتە كود كۆرسىتىدىغان سېتىۋېلىش يوق.','Could not show a new restore code: %s'=>'يېڭى ئەسلىگە كەلتۈرۈش كودىنى كۆرسىتەلمىدى: %s','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'يېڭى ئەسلىگە كەلتۈرۈش كودىڭىز: %s. ئۇنى بىخەتەر جايدا ساقلاڭ — ئالدىنقى كود ئىناۋەتسىز بولدى.','What is sent when Babilim checks this site'=>'Babilim بۇ تور بېكەتنى تەكشۈرگەندە يوللىنىدىغان مەزمۇن','(detected)'=>'(بايقالدى)','No language is managed yet.'=>'تېخى ھېچقانداق تىل باشقۇرۇلمايدۇ.','Babilim adds translations for every language checked here.'=>'Babilim بۇ يەردە تاللانغان ھەر بىر تىل ئۈچۈن تەرجىمە قوشىدۇ.','Add another language'=>'باشقا تىل قوشۇش','Choose a language…'=>'تىل تاللاڭ…','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'مۇلازىمەتتىن WordPress.org نىڭ تولۇق تىل تىزىمىنى يۈكلىگىلى بولمىدى، شۇڭا ھازىر باشقا تىل قوشقىلى بولمايدۇ.','Theme'=>'ئۆرنەك','Plugin'=>'قىستۇرما','Free quota'=>'ھەقسىز نورما','Downloads: %1$d/%2$d (%3$s)'=>'چۈشۈرۈش: %1$d/%2$d (%3$s)','Supplementary translation index'=>'تولۇقلىما تەرجىمە ئىندېكسى','Built'=>'قۇرۇلغان','Included'=>'كىرگۈزۈلگەن','Excluded'=>'چىقىرىۋېتىلگەن','Already in WordPress core'=>'WordPress يادروسىدا بار','Supplementary translation maintenance'=>'قوشۇمچە تەرجىمە ئىندېكسىنى ئاسراش','Maintenance status is not available right now.'=>'ئاسراش ھالىتىنى ھازىر كۆرگىلى بولمايدۇ.','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'%1$s دە تازىلاش توختىتىلدى: %2$s. ھېچnەرسە ئۆچۈرۈلمىدى.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'ئاخىرقى تازىلاش %1$s دە: %2$d يېڭىدىن بەلگىلەندى، %3$d ھۆججەت ئۆچۈرۈلدى، %4$d خاتىرە چىقىرىۋېتىلدى.','No cleanup has run yet.'=>'تېخى تازىلاش ئىجرا قىلىنمىدى.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'تەرجىمە ئىندېكسىغا يېزىش %1$s دا (%2$s) باشقا باشقا تەلەپ بىلەن توقۇنۇشۇپ قالدى ۋە ئىجرا قىلىنمىدى؛ ئەڭ يېڭى نەشرى ساقلاندى.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'%1$s دىكى تەرجىمە ئىندېكسىغا يېزىش (%2$s) تاماملانمىدى ۋە ئىجرا قىلىنمىدى (%3$s).','Maintenance'=>'ئاسراش','Rebuild index now'=>'ئىندېكسنى ھازىر قايتا قۇرۇش','Sweep now'=>'ھازىر تازىلاش','Danger zone'=>'خەتەرلىك رايون','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Babilim بۇ تور بېكەتتىكى ھەممە قىستۇرما ۋە ئۆرنەك ئۈچۈن قاچىلىغان بارلىق تىل ھۆججەتلىرىنى ئۆچۈرىدۇ.','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Babilim قاچىلىغان ھەممە نەرسىنى ئۆچۈرۈشمۇ؟ بۇ ئۇنىڭ بۇ تور بېكەتتىكى ھەممە قىستۇرما ۋە ئۆرنەك ئۈچۈن قاچىلىغان بارلىق تىل ھۆججەتلىرىنى ئۆچۈرىدۇ.','Remove everything Babilim installed'=>'Babilim قاچىلىغان ھەممە نەرسىنى ئۆچۈرۈش','This string is too long to be sent as a report, so no report form is offered for it.'=>'بۇ تېكىست دوكلات سۈپىتىدە ئەۋەتىشكە بەك ئۇزۇن، شۇڭا ئۇنىڭ ئۈچۈن دوكلات جەدۋىلى تەمىنلەنمەيدۇ.','Category'=>'تۈر','Choose a category…'=>'بىر تۈر تاللاڭ…','Roll back and send report'=>'ئەسلىگە قايتۇرۇپ دوكلات ئەۋەتىش','Send report'=>'دوكلات ئەۋەتىش','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'بۇ زاپچاسنىڭ بەزى تېكىستلىرى ئاپتورى تەرىپىدىن قاتتىق كودلانغان بولۇپ، تىل بوغچىسى ئارقىلىق تەرجىمە قىلغىلى بولمايدۇ.','WordPress.org'=>'WordPress.org','Bundled with the theme'=>'ئۆرنەك بىلەن بىللە كەلگەن','Bundled with the plugin'=>'قىستۇرما بىلەن بىللە كەلگەن','Upload was not accepted'=>'يۈكلەش قوبۇل قىلىنمىدى','Upload expired before it finished'=>'يۈكلەش ۋاقتى توشتى، تاماملانمىدى','No translation'=>'تەرجىمە يوق','Upload in progress — continue or cancel'=>'يۈكلەش داۋاملىشىۋاتىدۇ — داۋاملاشتۇرۇڭ ياكى بىكار قىلىڭ','Scheduled, waiting to be processed'=>'كۈنتەرتىپكە قويۇلغان، بىر تەرەپ قىلىنىشنى كۈتىۋاتىدۇ','Translating…'=>'تەرجىمە قىلىنىۋاتىدۇ…','Translation failed'=>'تەرجىمە مەغلۇپ بولدى','Free quota used'=>'ھەقسىز نورما ئىشلىتىلدى','Needs a paid license'=>'ھەقلىق ئىجازەتنامە كېرەك','Not supported'=>'قوللىمايدۇ','Status unknown'=>'ھالىتى نامەلۇم','translation statusInstalled'=>'قاچىلانغان','Update available'=>'يېڭىلاش بار','Removed after a failed integrity check'=>'پۈتۈنلۈكنى تەكشۈرۈش مەغلۇپ بولغاچقا ئۆچۈرۈلدى','Installed · built for %s, new version scheduled'=>'قاچىلانغان · %s نەشرىگە ئاساسەن ياسالغان، يېڭى نەشرى كۈنتەرتىپكە قويۇلدى','Installed · built for a different version, new version scheduled'=>'قاچىلانغان · باشقا نەشرىگە ئاساسەن ياسالغان، يېڭى نەشرى كۈنتەرتىپكە قويۇلدى','Installed · built for %s, translating the new version…'=>'قاچىلانغان · %s نەشرىگە ئاساسەن ياسالغان، يېڭى نەشرى تەرجىمە قىلىنىۋاتىدۇ…','Installed · built for a different version, translating the new version…'=>'قاچىلانغان · باشقا نەشرىگە ئاساسەن ياسالغان، يېڭى نەشرى تەرجىمە قىلىنىۋاتىدۇ…','Installed · built for %1$s, this site has %2$s'=>'قاچىلانغان · %1$s نەشرىگە ئاساسەن ياسالغان، بۇ تور بېكەتتە %2$s بار','Installed · built for %s'=>'قاچىلانغان · %s نەشرىگە ئاساسەن ياسالغان','Installed · built for a different version'=>'قاچىلانغان · باشقا نەشرىگە ئاساسەن ياسالغان','Installed · built for %s, new version failed'=>'ئورنىتىلدى · %s نەشرىگە ئاتاپ ئىشلەنگەن، يېڭى نەشرى مەغلۇپ بولدى','Installed · built for a different version, new version failed'=>'ئورنىتىلدى · باشقا نەشرىگە ئاتاپ ئىشلەنگەن، يېڭى نەشرى مەغلۇپ بولدى','Installed · built for %s, new version needs a paid license'=>'ئورنىتىلدى · %s ئۈچۈن قۇرۇلغان، يېڭى نەشرى ھەقلىق ئىجازەتنامە تەلەپ قىلىدۇ','Installed · built for a different version, new version needs a paid license'=>'ئورنىتىلدى · باشقا نەشرى ئۈچۈن قۇرۇلغان، يېڭى نەشرى ھەقلىق ئىجازەتنامە تەلەپ قىلىدۇ','Installed · built for %s, free quota used'=>'ئورنىتىلدى · %s ئۈچۈن قۇرۇلغان، ھەقسىز نورما ئىشلىتىلدى','Installed · built for a different version, free quota used'=>'ئورنىتىلدى · باشقا نەشرى ئۈچۈن قۇرۇلغان، ھەقسىز نورما ئىشلىتىلدى','translation statusAvailable'=>'ئىشلەتكىلى بولىدۇ','Installed · %s'=>'ئورنىتىلدى · %s','Available · %s'=>'ئىشلەتكىلى بولىدۇ · %s','Update'=>'يېڭىلاش','Download'=>'چۈشۈرۈش','Updating…'=>'يېڭىلىنىۋاتىدۇ…','Downloading…'=>'چۈشۈرۈلۈۋاتىدۇ…','Retry request'=>'تەلەپنى قايتا سىناش','Request newer translation'=>'يېڭىراق تەرجىمە تەلەپ قىلىش','Request translation'=>'تەرجىمە تەلەپ قىلىش','Requesting…'=>'تەلەپ قىلىنىۋاتىدۇ…','Requesting a translation uses one of your free slots, unless this component already uses one. A failed translation does not give the slot back.'=>'تەرجىمە تەلەپ قىلسىڭىز، بۇ زاپچاس ئىلگىرى ئورۇن ئىشلەتمىگەن بولسا، ھەقسىز ئورۇنلىرىڭىزنىڭ بىرى ئىشلىتىلىدۇ. مەغلۇپ بولغان تەرجىمە ئورۇننى قايتۇرمايدۇ.','If this component does not use one of your free slots yet, requesting a translation uses one. A failed translation does not give the slot back. Continue?'=>'بۇ زاپچاس تېخى ھەقسىز ئورۇنلىرىڭىزنىڭ بىرىنى ئىشلەتمىگەن بولسا، تەرجىمە تەلەپ قىلىش بىرىنى ئىشلىتىدۇ. مەغلۇپ بولغان تەرجىمە ئورۇننى قايتۇرمايدۇ. داۋاملاشتۇرامسىز؟','No plugins or themes found.'=>'قوشۇلما ياكى ئۆرنەك تېپىلمىدى.','Clear filters'=>'سۈزگۈچلەرنى تازىلاش','No components match these filters. %s'=>'بۇ سۈزگۈچلەرگە ماس كېلىدىغان زاپچاس يوق. %s','Select all'=>'ھەممىنى تاللاش','All'=>'ھەممىسى','Available'=>'ئىشلەتكىلى بولىدۇ','Updates'=>'يېڭىلانمىلار','Requestable'=>'تەلەپ قىلغىلى بولىدىغان','Installed'=>'ئورنىتىلغان','Plugins'=>'قوشۇلمىلار','Themes'=>'ئۆرنەكلەر','All languages'=>'بارلىق تىللار','%d to install'=>'%d ئورنىتىلىدۇ' . "\0" . '%d ئورنىتىلىدۇ','Language:'=>'تىل:','Bulk actions apply to every matching language of each selected component.'=>'تۈركۈملەپ مەشغۇلات تاللانغان ھەر بىر زاپچاسنىڭ ماس كېلىدىغان بارلىق تىللىرىغا قوللىنىلىدۇ.','Bulk actions apply only to the selected language of each selected component.'=>'تۈركۈملەپ مەشغۇلات تاللانغان ھەر بىر زاپچاسنىڭ پەقەت تاللانغان تىلىغىلا قوللىنىلىدۇ.','Version %s'=>'نەشرى %s','Theme · %s'=>'ئۆرنەك · %s','Plugin · %s'=>'قوشۇلما · %s','Remove the %2$s translation of %1$s from this site?'=>'بۇ بېكەتتىن %1$s نىڭ %2$s تەرجىمىسى چىقىرىۋېتىلسۇنمۇ؟','Roll back the %2$s translation of %1$s to the previous build?'=>'%1$s نىڭ %2$s تەرجىمىسىنى ئالدىنقى قۇرۇلما نەشرىگە قايتۇرامسىز؟','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','The registration challenge is not in the expected form.'=>'تىزىملاتقۇزۇش سىنىقى مۆلچەرلەنگەن شەكىلدە ئەمەس.','That is not a valid build identifier.'=>'بۇ ئىناۋەتلىك قۇرۇلما نەشرى ID سى ئەمەس.','Refusing to write outside the Babilim language-file directory.'=>'Babilim تىل ھۆججەت مۇندەرىجىسىنىڭ سىرتىغا يېزىشنى رەت قىلىدۇ.','Could not write the downloaded package to disk.'=>'چۈشۈرۈلگەن بوغچىنى دىسكىغا يازغىلى بولمىدى.','Unexpected HTTP %d response.'=>'كۈتۈلمىگەن HTTP %d ئىنكاسى.','This site\'s URL, so the service can verify you own it.'=>'بۇ تور بېكەتنىڭ URL ئادرېسى، شۇنداق بولغاندا مۇلازىمەت ئۇنىڭ سىزگە تەۋە ئىكەنلىكىنى دەلىللىيەلەيدۇ.','Your WordPress version, to serve compatible translation files.'=>'WordPress نەشرىڭىز، ماسلىشىدىغان تەرجىمە ھۆججەتلىرىنى تەمىنلەش ئۈچۈن.','Your PHP version, for compatibility.'=>'PHP نەشرىڭىز، ماسلىشىشچانلىقنى جەزملەش ئۈچۈن.','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'بۇ قىستۇرمىنىڭ ئۆز نەشرى، شۇنداق بولغاندا ئۇ بەك كونا بولۇپ مۇلازىمەت بىلەن ئالاقىلىشالمىسا، مۇلازىمەت سىزگە يېڭىلاشنى ئېيتالايدۇ.','This site\'s configured locale.'=>'بۇ تور بېكەتنىڭ تەڭشەلگەن تىل-رايونى.','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'بۇ تور بېكەتتە ئىشلىتىلىۋاتقان بارلىق تىل-رايونلار (تور بېكەت تىل-رايونى، ئورنىتىلغان تىل بوغچىلىرى، ئىشلەتكۈچى تىل-رايونلىرى ۋە قولدا قوشقانلىرىڭىز). ھېچقانداق تىل-رايونغا ئالاھىدە مۇئامىلە قىلىنمايدۇ.','(a public key generated for this site)'=>'(بۇ تور بېكەت ئۈچۈن ھاسىل قىلىنغان ئاشكارا ئاچقۇچ)','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'بۇ تور بېكەتنىڭ ئورنىتىش ئاشكارا ئاچقۇچى، ئىلتىماسلارنىڭ ھەقىقەتەن شۇ تور بېكەتتىن كەلگەنلىكىنى ئىسپاتلاش ئۈچۈن ئىشلىتىلىدۇ. پەقەت ئاشكارا قىسمىلا ئەۋەتىلىدۇ.','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'ئورنىتىلغان ھەر بىر قىستۇرما/ئۆرنەك: slug، نەشرى، تېكىست دائىرىسى (text domain)، WordPress.org تىزىملىكىدە بار-يوقلۇقى، ئۆزى بىللە كەلگەن تىللار ۋە قايسى تىللار ئۈچۈن Babilim تەرجىمىسى ئورنىتىلغانلىقى.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: that component\'s entire directory, as a zip.'=>'پەقەت WordPress.org دا يوق قىستۇرما ياكى ئۆرنەك ئۈچۈن يۈكلەشنى جەزملىگەندىلا: شۇ زاپچاسنىڭ پۈتۈن مۇندەرىجىسى zip شەكلىدە.','(generic codes and coordinates only)'=>'(پەقەت ئومۇمىي كودلار ۋە كوئوردېناتلار)','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'كۈتۈۋاتقان ئەڭ كۆپ بولغاندا 20 دىئاگنوز ۋەقەلىرى (مەسىلەن پۈتۈنلۈكنى تەكشۈرۈشتە مەغلۇپ بولغان ھۆججەت)، ھەر بىرى پەقەت كود، زاپچاس ۋە تىل بولۇپ، ھېچقانداق تېكىست مەزمۇنى ياكى تەرجىمە قىلىنغان تېكىست يوق.','Unsafe locale: %s'=>'بىخەتەر بولمىغان تىل-رايون: %s','Manifest unavailable: %s'=>'Manifest ئىشلەتكىلى بولمايدۇ: %s','Could not determine active components; the existing merged index was left unchanged.'=>'ئاكتىپ زاپچاسلارنى ئېنىقلىغىلى بولمىدى؛ مەۋجۇت بىرلەشتۈرۈلگەن ئىندېكس ئۆزگەرتىلمىدى.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'ئورنىتىلغان قىستۇرما/ئۆرنەكلەرنى ئېنىقلىغىلى بولمىدى؛ تازىلاش ئاتلاندى، ھېچنېمە ئۆچۈرۈلمىدى.','Sweep aborted without orphaning anything: %s.'=>'تازىلاش ھېچقانداق نەرسىنى يېتىم قىلماستىن توختىتىلدى: %s.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'تازىلاش ئىجرا قىلىندى، لېكىن بەزى ئۆزگىرىشلەرنى تەرجىمە ئىندېكسىغا خاتىرىلىگىلى بولمىدى؛ كېيىنكى تازىلاشتا قايتا سىنىلىدۇ.','component kind in the sweep brake messagetheme'=>'ئۆرنەك','component kind in the sweep brake messageplugin'=>'قىستۇرما','it would orphan every managed %1$s component (%2$d of %2$d)'=>'بارلىق باشقۇرۇلىدىغان %1$s زاپچاسلىرىنى (%2$d نىڭ %2$d ى) يېتىم قىلىپ قويىدۇ','it would orphan %1$d of %2$d managed components (more than half)'=>'باشقۇرۇلىدىغان %2$d زاپچاسنىڭ %1$d ىنى يېتىم قىلىپ قويىدۇ (yېرىمىدىن كۆپ)','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'\'%s\' ئۈچۈن بىرلەشتۈرۈلگەن ئىندېكس قايتا قۇرۇلدى، لېكىن تەرجىمە ئىندېكسى ئۇنى خاتىرىلىيەلمىدى؛ كېيىنكى قايتا قۇرۇش قايتا سىنايدۇ.','Could not write the staged merged index.'=>'باسقۇچلۇق بىرلەشتۈرۈلگەن ئىندېكسنى يازغىلى بولمىدى.','Re-parsed entry count did not match the built index.'=>'قايتا ئانالىز قىلىنغان خاتىرە سانى قۇرۇلغان ئىندېكسقا ماس كەلمىدى.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'\'%s\' ئۈچۈن بىرلەشتۈرۈلگەن ئىندېكسنى ئورنىغا يۆتكىگىلى بولمىدى؛ ئالدىنقى ئىشلىتىلىۋاتقان ئىندېكس (بولسا) يېرىم يېڭىلانغان ھالەتتە قالدۇرۇلماي ئۆچۈرۈلدى. كېيىنكى مۇۋەپپەقىyەتلىك قايتا قۇرۇشقىچە بۇ تىل ئۈچۈن سۈكۈتتىكى دائىرە تولۇقلىمىسى تەمىنلەنمەيدۇ.','Could not open zip: %s'=>'zip نى ئاچقىلى بولمىدى: %s','Zip has no manifest.json.'=>'Zip ئىچىدە manifest.json يوق.','manifest.json in the zip is not valid JSON.'=>'zip ئىچىدىكى manifest.json ئۈنۈملۈك JSON ئەمەس.','manifest.json\'s \'%s\' does not match the expected value.'=>'manifest.json دىكى \'%s\' كۈتۈلگەن قىممەتكە ماس كەلمىدى.','Another installation is running; try again in a moment.'=>'باشقا بىر ئورنىتىش ئىجرا بولۇۋاتىدۇ؛ سەل تۇرۇپ قايتا سىناڭ.','Not a valid server_build_id: %s'=>'ئۈنۈملۈك server_build_id ئەمەس: %s','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'بوغچا manifest ىنىڭ تۈرى \'%1$s\' تەلەپ قىلىنغان تۈر \'%2$s\' غا ماس كەلمىدى.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'بوغچىنىڭ تېكىست دائىرىسى (text domain) \'%1$s\' بۇ بېكەتتىكى بۇ زاپچاسنىڭ (\'%2$s\') نۇسخىسىغا ماس كەلمىدى، شۇڭا ئورنىتىلمىدى.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'بېرىلگەن دائىرە \'%1$s\' بوغچا manifest ىنىڭ ئۆزىنىڭ slug قىممىتى \'%2$s\' غىمۇ، text_domain قىممىتى \'%3$s\' غىمۇ ماس كەلمىدى.','Unsafe slug: %s'=>'بىخەتەر بولمىغان slug: %s','Unsafe text_domain: %s'=>'بىخەتەر بولمىغان text_domain: %s','The package has no %s for its own text domain.'=>'بوغچىدا ئۆزىنىڭ تېكىست دائىرىسى (text domain) ئۈچۈن %s يوق.','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json دا \'%s يوق ياكى ئۈنۈمسىز.','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json دا \'entries\' يوق ياكى ئۈنۈمسىز.','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json دا \'files\' يوق ياكى ئۈنۈمسىز.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json دا \'extra_domains\' يوق ياكى ئۈنۈمسىز.','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json دا \'build_no\' يوق ياكى ئۈنۈمسىز.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'manifest.json دىكى \'server_build_id\' ئۈنۈملۈك قۇرۇلما نەشرى ID سى ئەمەس.','manifest.json\'s \'contract\' is not a valid version string.'=>'manifest.json دىكى \'contract\' ئۈنۈملۈك نەشر تىزمىسى ئەمەس.','manifest.json\'s \'status\' must be \'published\'.'=>'manifest.json دىكى \'status\' چوقۇم \'published\' بولۇشى كېرەك.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'manifest.json دىكى \'kind\' چوقۇم \'plugin\' ياكى ئۆرنەك (\'theme\') بولۇشى كېرەك.','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json دىكى \'default_domain_entries\' ئۈنۈمسىز.','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json دىكى \'default_domain_files\' ئۈنۈمسىز.','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest دا \'%s\' يوق ياكى ئۈنۈمسىز.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'expected_manifest دىكى \'server_build_id\' ئۈنۈملۈك قۇرۇلما نەشرى ID سى ئەمەس.','No record for %s'=>'%s ئۈچۈن خاتىرە يوق','One or more served files no longer match the manifest.'=>'تارقىتىلغان بىر ياكى بىر قانچە ھۆججەت manifest غا ماس كەلمەيدۇ.','No previous build to roll back to.'=>'ئەسلىگە قايتۇرىدىغان ئالدىنقى قۇرۇلما نەشرى يوق.','The change could not be recorded in the translation index; please try again.'=>'بۇ ئۆزگەرتىشنى تەرجىمە ئىندېكسىغا خاتىرىلىگىلى بولمىدى؛ قايتا سىناپ بېقىڭ.','Unknown kind: %s'=>'نامەلۇم تۈر: %s','Unsafe domain: %s'=>'بىخەتەر بولمىغان دائىرە: %s','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'تېكىست دائىرىسى (text domain) \'%1$s\' (%2$s) باشقا ئورنىتىلغان زاپچاس (%3$s) ئۈچۈن ئىشلىتىلىۋاتىدۇ؛ ھېچنېمە ئورنىتىلمىدى.','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'ئەسلىگە قايتۇرۇش \'%1$s\' (%2$s) نى قاپلىۋېتىدۇ، ئۇ ھازىر باشقا ئورنىتىلغان زاپچاس (%3$s) ئۈچۈن ئىشلىتىلىۋاتىدۇ؛ ھېچنېمە ئۆزگەرتىلمىدى.','Zip is missing expected file: %s'=>'Zip ئىچىدە كۈتۈلگەن ھۆججەت يوق: %s','sha256 mismatch for %s'=>'%s نىڭ sha256 ماس كەلمىدى','The package declares no main translation file.'=>'بۇ بوغچىدا ئاساسىي تەرجىمە ھۆججىتى جاكارلانمىغان.','Zip is missing expected default file: %s'=>'Zip ئىچىدە كۈتۈلگەن كۆڭۈلدىكى ھۆججەت يوق: %s','sha256 mismatch for default/%s'=>'default/%s نىڭ sha256 ماس كەلمىدى','Could not stage %s'=>'%s نى تەييارلىغىلى بولمىدى','Could not stage default/%s'=>'default/%s نى تەييارلىغىلى بولمىدى','Entry count mismatch for %s'=>'%s نىڭ تۈر سانى ماس كەلمىدى','Could not verify entry count for %s'=>'%s نىڭ تۈر سانىنى دەلىللىگىلى بولمىدى','l10n.php entry count mismatch for %s'=>'%s نىڭ l10n.php مەزمۇن سانى ماس كەلمىدى','Default supplement entry count mismatch.'=>'كۆڭۈلدىكى قوشۇمچە تۈر سانى ماس كەلمىدى.','The package produced no servable main translation file.'=>'بۇ بوغچىدىن تارقىتىشقا بولىدىغان ئاساسىي تەرجىمە ھۆججىتى چىقمىدى.','Could not prepare %s for rollback.'=>'%s نى ئەسلىگە قايتۇرۇشقا تەييارلىغىلى بولمىدى.','Could not back up %s before replacing it.'=>'%s نى ئالماشتۇرۇشتىن بۇرۇن زاپاسلىغىلى بولمىدى.','Could not move %s into place.'=>'%s نى ئورنىغا يۆتكىگىلى بولمىدى.','Could not read %s back after moving it into place.'=>'%s ئورنىغا يۆتكەلگەندىن كېيىن قايتا ئوقۇغىلى بولمىدى.','English (United States)'=>'English (United States)','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest ئىشلەتكىلى بولمايدۇ: %s','could not read _manifest.json: %s'=>'_manifest.json نى ئوقۇغىلى بولمىدى: %s','failed to parse _manifest.json: %s'=>'_manifest.json نى تەھلىل قىلىش مەغلۇپ بولدى: %s','_manifest.json has an unexpected structure'=>'_manifest.json نىڭ قۇرۇلمىسى كۈتۈلگەنگە ماس كەلمەيدۇ','Could not create the package archive.'=>'بوغچا ئارخىپىنى قۇرالمىدى.','No writable temporary directory is available for packaging.'=>'بوغچىلاش ئۈچۈن يېزىشقا بولىدىغان ۋاقىتلىق مۇندەرىجە يوق.','A file in the component could not be read, so it was not packaged.'=>'زاپچاسنىڭ ئىچىدىكى بىر ھۆججەتنى ئوقۇغىلى بولمىدى، شۇڭا بوغچىلانمىدى.','Only plugins and themes can be packaged.'=>'پەقەت قىستۇرمىلار ۋە ئۆرنەكلەرنىلا بوغچىلاشقا بولىدۇ.','The component\'s main file was not found.'=>'زاپچاسنىڭ ئاساسىي ھۆججىتى تېپىلمىدى.','The component is not inside the plugins or themes directory.'=>'زاپچاس قىستۇرمىلار ياكى ئۆرنەكلەر مۇندەرىجىسىنىڭ ئىچىدە ئەمەس.','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim نىڭ بۇ بىر باسقۇچتىكى ۋاقتى توشتى، كېيىنكى تەكشۈرۈشتە داۋاملاشتۇرىدۇ.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim بۇ تور بېكەتنى دەلىللىيەلمىدى، شۇڭا دەلىللەش مۇۋەپپەقىيەتلىك بولغۇچە ھېچنېمە چۈشۈرۈلمەيدۇ ياكى قاچىلانمايدۇ.','Registration response was missing required fields.'=>'تىزىملىتىش جاۋابىدا زۆرۈر بۆلەكلەر كەم.','No pending challenge to verify.'=>'دەلىللەشنى كۈتۈۋاتقان سىناق يوق.','Verify response was missing site_token.'=>'دەلىللەش جاۋابىدا site_token كەم ئىكەن.','No site id is on file to rotate a token for.'=>'بەلگە (token) نى ئالماشتۇرىدىغان تور بېكەت ID سى خاتىرىلەنمىگەن.','Rotate-token response was missing site_token.'=>'بەلگىنى ئالماشتۇرۇش جاۋابىدا site_token كەم ئىكەن.','nonce must be a hexadecimal string.'=>'nonce چوقۇم ئون ئالتىلىك تىزما بولۇشى كېرەك.','No pending challenge for this nonce.'=>'بۇ nonce ئۈچۈن كۈتۈۋاتقان خىرىس يوق.','Too many requests.'=>'تەلەپ بەك كۆپ.','The service asked this site to wait before syncing again.'=>'مۇلازىمەت بۇ بېكەتتىن قايتا ماسقەدەملەشتىن بۇرۇن ساقلاشنى تەلەپ قىلدى.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'بۇ بېكەتتە %2$d تىلدا %1$d زاپچاس بار، %3$d تەكشۈرۈش تۈركۈمى لازىم؛ Babilim ھەر قېتىمدا ئەڭ كۆپ بولغاندا %4$d نى بىر تەرەپ قىلالايدۇ. تەڭشەكلەردە باشقۇرۇلىدىغان تىللارنى ئازايتىڭ ياكى ئىشلىتىلمەيدىغان قىستۇرما ۋە ئۆرنەكلەرنى چەكلەڭ، ئاندىن ھازىر قايتا تەكشۈرۈش نى بېسىڭ.','Babilim could not finish checking this site.'=>'Babilim بۇ تور بېكەتنى تەكشۈرۈپ بولالمىدى.','This site\'s address is too long for Babilim to register.'=>'بۇ تور بېكەتنىڭ ئادرېسى بەك ئۇزۇن، Babilim تىزىملىتالمايدۇ.','This site\'s locale code is not one Babilim can register.'=>'بۇ تور بېكەتنىڭ تىل كودىنى Babilim تىزىملىتالمايدۇ.','The download response was missing a usable location.'=>'چۈشۈرۈش جاۋابىدا ئىشلەتكىلى بولىدىغان ئورۇن يوق ئىكەن.','The service\'s upload offer was incomplete.'=>'مۇلازىمەتنىڭ يۈكلەش تەكلىپى تولۇق ئەمەس ئىكەن.','This component is larger than the service accepts, so it cannot be uploaded.'=>'بۇ زاپچاس مۇلازىمەت قوبۇل قىلىدىغان چوڭلۇقتىن ئېشىپ كەتتى، شۇڭا يوللىغىلى بولمايدۇ.','The packaged component could not be read.'=>'بوغچىلانغان زاپچاسنى ئوقۇغىلى بولمىدى.','A part of the upload kept failing, so the upload was cancelled.'=>'يۈكلەشنىڭ بىر قىسمى توختىماي مەغلۇپ بولدى، شۇڭا يۈكلەش ئەمەلدىن قالدۇرۇلدى.','Could not read: %s'=>'ئوقۇغىلى بولمىدى: %s']];